### Rust Boundary Design (Thin Layer)

```rust
// src/process/focus.rs - ONLY WinAPI access, NO business logic

#[napi(object)]
pub struct FocusedWindow {
    pub pid: u32,
    pub process: String,
    pub process_name: String,
    pub path: String,
    pub main_window_title: String,
    pub has_window: bool,
}

#[napi]
pub fn get_focused_window() -> Result<Option<FocusedWindow>> {
    let start = Instant::now();

    // ONLY: GetForegroundWindow, GetWindowThreadProcessId, OpenProcess
    let result = unsafe { get_focused_window_impl() };

    let elapsed = start.elapsed();
    tracing::debug!(
        target: "native:focus",
        latency_us = elapsed.as_micros(),
        "get_focused_window completed"
    );

    result
}

// NO orchestration, NO caching, NO state management
// Business logic stays in backend/processes.js
```

### Contract Parity Test Example

```javascript
// test/contract-parity-focus.js

const nativeFocus = require('../backend/native-focus');
const { PowerShellServer } = require('../backend/powershell-server');

async function testFocusedAppContract() {
  console.log('[contract-parity] Testing focused app...');

  // Run both implementations
  const [nativeResult, psResult] = await Promise.all([
    nativeFocus.getFocusedWindow(),
    runPowerShellFocusedApp()
  ]);

  // Compare structure
  const nativeKeys = Object.keys(nativeResult.application || {}).sort();
  const psKeys = Object.keys(psResult.application || {}).sort();

  if (JSON.stringify(nativeKeys) !== JSON.stringify(psKeys)) {
    console.error('[contract-parity] MISMATCH: Field presence differs');
    console.error('Native fields:', nativeKeys);
    console.error('PowerShell fields:', psKeys);
    process.exit(1);
  }

  // Compare types
  for (const key of nativeKeys) {
    const nativeType = typeof nativeResult.application[key];
    const psType = typeof psResult.application[key];

    if (nativeType !== psType) {
      console.error(`[contract-parity] MISMATCH: ${key} type differs`);
      console.error(`  Native: ${nativeType}, PowerShell: ${psType}`);
      process.exit(1);
    }
  }

  console.log('[contract-parity] ✓ Focused app contract matches');
}
```

### Benchmark Example

```javascript
// benchmark/bench-focus.js

const nativeFocus = require('../backend/native-focus');
const { performance } = require('perf_hooks');

async function benchmarkFocusedApp() {
  console.log('[benchmark] Focused app latency test...');

  const iterations = 100;
  const latencies = [];

  // Cold start
  const coldStart = performance.now();
  await nativeFocus.getFocusedWindow();
  const coldLatency = performance.now() - coldStart;

  // Warm calls
  for (let i = 0; i < iterations; i++) {
    const start = performance.now();
    await nativeFocus.getFocusedWindow();
    latencies.push(performance.now() - start);
  }

  latencies.sort((a, b) => a - b);
  const avg = latencies.reduce((a, b) => a + b) / latencies.length;
  const p95 = latencies[Math.floor(latencies.length * 0.95)];

  console.log(`[benchmark] Cold start: ${coldLatency.toFixed(2)}ms`);
  console.log(`[benchmark] Avg: ${avg.toFixed(2)}ms`);
  console.log(`[benchmark] P95: ${p95.toFixed(2)}ms`);

  return { coldLatency, avg, p95 };
}
```

### Structured Logging Example

```javascript
// backend/native-focus.js

const nativeFocusBinding = require('../faderdeck-native');
const { USE_NATIVE_FOCUS } = require('./feature-flags');

async function getFocusedWindow() {
  if (!USE_NATIVE_FOCUS) {
    console.log('[native:focus] Feature disabled, using PowerShell');
    return fallbackToPowerShell();
  }

  const start = Date.now();

  try {
    const result = await nativeFocusBinding.getFocusedWindow();
    const latency = Date.now() - start;

    if (process.env.NODE_ENV === 'development') {
      console.log(`[native:focus] Success in ${latency}ms`);
    }

    return result;
  } catch (error) {
    const latency = Date.now() - start;
    console.error(`[native:focus] Failed after ${latency}ms:`, error);
    console.log('[native:focus] Activating PowerShell fallback');
    return fallbackToPowerShell();
  }
}
```

### Updated Implementation Order

1. **Setup workspace** (Task 1) - Add tracing
2. **Focused app APIs** (Task 2) - With logging
3. **Process enumeration** (Task 3) - With logging
4. **Node.js wrappers** (Task 4) - With latency logging
5. **Contract parity tests** (Task 5) - **MUST PASS**
6. **Benchmark tooling** (Task 6) - **MUST MEET TARGETS**
7. **Backend integration** (Task 7) - With fallback logging
8. **Validate & document** (Task 8) - Update RUST_BACKEND_PROGRESS.md

### Success Criteria (Updated)

**Phase 2 (Focused App):**
- ✅ Contract parity test passes
- ✅ Benchmark: avg <5ms, p95 <10ms, cold <20ms
- ✅ Structured logging works
- ✅ Fallback activates on error
- ✅ No renderer changes

**Phase 1 (Process Enumeration):**
- ✅ Contract parity test passes
- ✅ Benchmark: avg <100ms, p95 <150ms, cold <200ms
- ✅ Structured logging works
- ✅ Fallback activates on error
- ✅ No renderer changes

**Both Phases:**
- ✅ PowerShell NOT removed until benchmarks validated
- ✅ RUST_BACKEND_PROGRESS.md updated with results
- ✅ Zero breaking changes to IPC contract
- ✅ Thin Rust boundary (no business logic)

