const path = require('path');
const { execFile } = require('child_process');
const { promisify } = require('util');

const execFileAsync = promisify(execFile);
const SCRIPT_PATH = path.join(__dirname, 'scripts', 'audio-session.ps1');
const WORKER_SCRIPT_PATH = path.join(
  __dirname,
  'scripts',
  'audio-session-worker.ps1'
);
const SESSION_SNAPSHOT_CACHE_MS = 90;
const SESSION_SNAPSHOT_BACKGROUND_REFRESH_MS = 45;

const { PowerShellServer } = require('./powershell-server');

function parseJsonOutput(stdout) {
  if (!stdout || !stdout.trim()) {
    return null;
  }

  return JSON.parse(stdout);
}

class AudioSessionBridge extends PowerShellServer {
  constructor(logFunction) {
    super({
      log: logFunction || (() => {}),
      scriptPath: WORKER_SCRIPT_PATH,
      spawnArgs: [],
      requestTimeoutMs: 8000,
      responseSuccessKey: 'success',
      logPrefix: 'audio_session_worker',
      buffering: 'manual'
    });

    this._sessionSnapshot = {
      applications: [],
      fetchedAt: 0,
      refreshPromise: null
    };

    this._pendingRequestId = 0;
    this._pendingResolve = null;
    this._pendingReject = null;
    this._pendingTimeoutId = null;
  }

  /** @override — omit null-valued fields to match the worker's expectations */
  _writePayload(_stdin, id, action, options) {
    return {
      id,
      action,
      processName: options.processName || '',
      volume: typeof options.volume === 'number' ? options.volume : null,
      mute: typeof options.mute === 'boolean' ? options.mute : null,
      processNames: Array.isArray(options.processNames) ? options.processNames : []
    };
  }

  /**
   * @override — use 'success' instead of 'ok' for error detection.
   * Falls back to runWithScript when the worker is unavailable.
   */
  _onResponse(pending, parsedMessage) {
    if (parsedMessage?.success !== false) {
      pending.resolve(parsedMessage?.result ?? null);
    } else {
      pending.reject(
        new Error(
          String(parsedMessage?.error || 'Audio worker request failed')
        )
      );
    }
  }

  /** @override — audio-sessions does not pass '-Action serve' */
  _buildSpawnArgs() {
    return ['-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', this._scriptPath];
  }

  // ─── run() override with runWithScript fallback ──────────────────────────────

  /**
   * @override
   * Sends a request to the worker, falling back to runWithScript on error.
   */
  async run(action, options = {}) {
    try {
      return await super.run(action, options);
    } catch (error) {
      this._log('audio_session_worker error, fallback to execFile:', error);
      return this.runWithScript(action, options);
    }
  }

  // ─── Standalone one-shot script execution ───────────────────────────────────

  async runWithScript(action, options = {}) {
    const args = [
      '-NoProfile',
      '-ExecutionPolicy',
      'Bypass',
      '-File',
      SCRIPT_PATH,
      '-Action',
      action
    ];

    if (options.processName) {
      args.push('-ProcessName', options.processName);
    }

    if (typeof options.volume === 'number') {
      args.push('-Volume', String(options.volume));
    }

    if (typeof options.mute === 'boolean') {
      args.push('-Mute', options.mute ? 'true' : 'false');
    }

    if (Array.isArray(options.processNames)) {
      args.push('-ProcessNamesJson', JSON.stringify(options.processNames));
    }

    const { stdout } = await execFileAsync('powershell.exe', args, {
      windowsHide: true,
      maxBuffer: 10 * 1024 * 1024
    });

    return parseJsonOutput(stdout);
  }

  // ─── Session snapshot caching ─────────────────────────────────────────────

  filterSessionApplications(applications = [], processNames = []) {
    const normalizedFilters = [
      ...new Set(
        (Array.isArray(processNames) ? processNames : [])
          .map((processName) =>
            String(processName || '')
              .trim()
              .toLowerCase()
          )
          .filter(Boolean)
      )
    ];

    if (!normalizedFilters.length) {
      return Array.isArray(applications) ? applications.slice() : [];
    }

    const filterSet = new Set(normalizedFilters);
    return (Array.isArray(applications) ? applications : []).filter(
      (application) =>
        filterSet.has(
          String(application?.process || '')
            .trim()
            .toLowerCase()
        )
    );
  }

  patchCachedSessionApplications(processName, patch = {}) {
    const normalizedProcessName = String(processName || '')
      .trim()
      .toLowerCase();

    if (
      !normalizedProcessName ||
      !Array.isArray(this._sessionSnapshot.applications)
    ) {
      return;
    }

    this._sessionSnapshot.applications = this._sessionSnapshot.applications.map(
      (application) => {
        if (
          String(application?.process || '')
            .trim()
            .toLowerCase() !== normalizedProcessName
        ) {
          return application;
        }

        return {
          ...application,
          ...patch
        };
      }
    );
  }

  async refreshSessionSnapshot(options = {}) {
    if (!options?.force && this._sessionSnapshot.refreshPromise) {
      return this._sessionSnapshot.refreshPromise;
    }

    this._sessionSnapshot.refreshPromise = this.run('GetSessions', {
      processNames: []
    })
      .then((result) => {
        this._sessionSnapshot.applications = Array.isArray(result?.applications)
          ? result.applications
          : [];
        this._sessionSnapshot.fetchedAt = Date.now();
        return this._sessionSnapshot.applications.slice();
      })
      .finally(() => {
        this._sessionSnapshot.refreshPromise = null;
      });

    return this._sessionSnapshot.refreshPromise;
  }

  async listSessions(processNames = []) {
    try {
      const now = Date.now();
      const hasSnapshot =
        Array.isArray(this._sessionSnapshot.applications) &&
        this._sessionSnapshot.applications.length > 0;
      const snapshotAge = hasSnapshot
        ? now - this._sessionSnapshot.fetchedAt
        : Number.POSITIVE_INFINITY;

      if (hasSnapshot && snapshotAge < SESSION_SNAPSHOT_CACHE_MS) {
        if (snapshotAge >= SESSION_SNAPSHOT_BACKGROUND_REFRESH_MS) {
          void this.refreshSessionSnapshot().catch((error) => {
            this._log('audio_session_background_refresh error:', error);
          });
        }

        return this.filterSessionApplications(
          this._sessionSnapshot.applications,
          processNames
        );
      }

      if (this._sessionSnapshot.refreshPromise && hasSnapshot) {
        return this.filterSessionApplications(
          this._sessionSnapshot.applications,
          processNames
        );
      }

      const applications = await this.refreshSessionSnapshot({ force: true });
      return this.filterSessionApplications(applications, processNames);
    } catch (error) {
      this._log('audio_session_list error:', error);
      return [];
    }
  }

  async setVolume(processName, volume) {
    try {
      const result = await this.run('SetVolume', { processName, volume });
      this.patchCachedSessionApplications(processName, {
        volume: Number.isFinite(Number(volume)) ? Number(volume) : undefined,
        muted: Number(volume) <= 0
      });
      return result;
    } catch (error) {
      this._log('audio_session_set_volume error:', error);
      return null;
    }
  }

  async setVolumeBatch(entries = []) {
    if (!entries.length) {
      return { success: true, updatedCount: 0 };
    }

    try {
      const volumeMap = {};
      entries.forEach(([processName, volume]) => {
        volumeMap[processName] = volume;
      });

      return await this.run('SetVolumeBatch', { volumeMap });
    } catch (error) {
      this._log('audio_session_set_volume_batch error:', error);
      return null;
    }
  }

  async setMute(processName, mute) {
    try {
      const result = await this.run('SetMute', { processName, mute });
      this.patchCachedSessionApplications(processName, {
        muted: Boolean(mute)
      });
      return result;
    } catch (error) {
      this._log('audio_session_set_mute error:', error);
      return null;
    }
  }

  async prewarm() {
    try {
      await this.refreshSessionSnapshot({ force: true });
    } catch (error) {
      this._log('audio_session_prewarm error:', error);
    }
  }

  shutdown() {
    this.stopProcess('Audio worker shutdown');
  }
}

module.exports = { AudioSessionBridge };

const path = require('path');
const SCRIPT_PATH = path.join(__dirname, 'scripts', 'audio-device.ps1');
const { PowerShellServer } = require('./powershell-server');

function normalizeFlow(flow = '') {
  const normalized = String(flow || '')
    .trim()
    .toLowerCase();

  if (normalized === 'output' || normalized === 'render') {
    return 'output';
  }

  if (normalized === 'input' || normalized === 'capture') {
    return 'input';
  }

  return 'all';
}

class AudioDeviceManager extends PowerShellServer {
  constructor(logFunction) {
    super({
      log: logFunction || (() => {}),
      scriptPath: SCRIPT_PATH,
      spawnArgs: ['-Action', 'serve'],
      requestTimeoutMs: 8000,
      responseSuccessKey: 'ok',
      logPrefix: 'audio-device-server',
      buffering: 'readline'
    });
  }

  async listDevices(flow = 'all') {
    const normalizedFlow = normalizeFlow(flow);
    const parsed = await this.run('list', { flow: normalizedFlow });
    const devices = Array.isArray(parsed) ? parsed : [parsed];

    return {
      success: true,
      flow: normalizedFlow,
      devices
    };
  }

  async setDefaultDevice(deviceId = '', flow = 'all') {
    const normalizedDeviceId = String(deviceId || '').trim();
    const normalizedFlow = normalizeFlow(flow);

    if (!normalizedDeviceId) {
      return {
        success: false,
        error: 'missing-device-id'
      };
    }

    this._log('set_default_audio_device', normalizedFlow, normalizedDeviceId);
    return await this.run('set-default', {
      flow: normalizedFlow,
      deviceId: normalizedDeviceId
    });
  }

  async setVolume(deviceId = '', volume = 100, flow = 'all') {
    const normalizedDeviceId = String(deviceId || '').trim();
    const normalizedFlow = normalizeFlow(flow);

    if (!normalizedDeviceId) {
      return {
        success: false,
        error: 'missing-device-id'
      };
    }

    this._log(
      'set_audio_device_volume',
      normalizedFlow,
      normalizedDeviceId,
      volume
    );
    return await this.run('set-volume', {
      flow: normalizedFlow,
      deviceId: normalizedDeviceId,
      volume: Number(volume)
    });
  }

  async setMute(deviceId = '', muted = false, flow = 'all') {
    const normalizedDeviceId = String(deviceId || '').trim();
    const normalizedFlow = normalizeFlow(flow);

    if (!normalizedDeviceId) {
      return {
        success: false,
        error: 'missing-device-id'
      };
    }

    this._log(
      'set_audio_device_mute',
      normalizedFlow,
      normalizedDeviceId,
      muted
    );
    return await this.run('set-mute', {
      flow: normalizedFlow,
      deviceId: normalizedDeviceId,
      muted: Boolean(muted)
    });
  }
}

module.exports = {
  AudioDeviceManager
};

const os = require('os');
const path = require('path');
const { execFile } = require('child_process');
const { promisify } = require('util');

const execFileAsync = promisify(execFile);
const SCRIPT_PATH = path.join(__dirname, 'scripts', 'process-list.ps1');
const FOCUSED_SCRIPT_PATH = path.join(
  __dirname,
  'scripts',
  'focused-application.ps1'
);
const WINDOWS_DIRECTORY = (process.env.WINDIR || 'C:\\Windows').toLowerCase();
const SYSTEM_PATH_PREFIXES = [
  path.join(WINDOWS_DIRECTORY, 'system32'),
  path.join(WINDOWS_DIRECTORY, 'syswow64'),
  path.join(WINDOWS_DIRECTORY, 'winsxs')
].map((entry) => entry.toLowerCase());
const IGNORED_PROCESS_NAMES = new Set([
  'idle',
  'system',
  'registry',
  'memory compression',
  'secure system'
]);

function parseJsonArray(stdout) {
  if (!stdout || !stdout.trim()) {
    return [];
  }

  const parsed = JSON.parse(stdout);
  return Array.isArray(parsed) ? parsed : [parsed];
}

function isSystemPath(entryPath) {
  if (!entryPath) {
    return false;
  }

  const normalizedPath = entryPath.toLowerCase();
  return SYSTEM_PATH_PREFIXES.some((prefix) =>
    normalizedPath.startsWith(prefix)
  );
}

function humanizeProcessName(processName) {
  const baseName = String(processName || '')
    .replace(/\.exe$/i, '')
    .replace(/[_-]+/g, ' ')
    .trim();

  if (!baseName) {
    return 'Unknown app';
  }

  return baseName.replace(/\b\w/g, (match) => match.toUpperCase());
}

function normalizeProcess(rawProcess) {
  const processFile =
    String(rawProcess.Process || '').trim() ||
    `${String(rawProcess.ProcessName || '').trim()}.exe`;
  const processName = String(rawProcess.ProcessName || '').trim();
  const executable = processFile || `${processName}.exe`;
  const executablePath = String(rawProcess.Path || '').trim();
  const mainWindowTitle = String(rawProcess.MainWindowTitle || '').trim();
  const processKey = executable.toLowerCase();

  return {
    process: executable,
    processKey,
    processName,
    path: executablePath,
    mainWindowTitle,
    hasWindow: Boolean(mainWindowTitle),
    pid: Number(rawProcess.Id) || 0,
    name: humanizeProcessName(executable)
  };
}

function shouldIncludeProcess(entry) {
  if (
    !entry.process ||
    IGNORED_PROCESS_NAMES.has(entry.processName.toLowerCase())
  ) {
    return false;
  }

  if (entry.hasWindow) {
    return true;
  }

  if (!entry.path) {
    return false;
  }

  return !isSystemPath(entry.path);
}

const { PowerShellServer } = require('./powershell-server');

class ProcessCatalog {
  constructor(logFunction) {
    this._log = logFunction || (() => {});
    this._focusServer = new PowerShellServer({
      log: this._log,
      scriptPath: FOCUSED_SCRIPT_PATH,
      spawnArgs: ['-Action', 'serve'],
      requestTimeoutMs: 3000,
      responseSuccessKey: 'ok',
      logPrefix: 'focused-application-server',
      buffering: 'readline'
    });
  }

  async listRunningApplications() {
    if (os.platform() !== 'win32') {
      return [];
    }

    try {
      const { stdout } = await execFileAsync(
        'powershell.exe',
        ['-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', SCRIPT_PATH],
        { windowsHide: true, maxBuffer: 10 * 1024 * 1024 }
      );

      const rawProcesses = parseJsonArray(stdout);
      const uniqueApplications = new Map();

      rawProcesses
        .map(normalizeProcess)
        .filter(shouldIncludeProcess)
        .forEach((entry) => {
          const existing = uniqueApplications.get(entry.processKey);

          if (existing) {
            existing.instanceCount += 1;

            if (!existing.mainWindowTitle && entry.mainWindowTitle) {
              existing.mainWindowTitle = entry.mainWindowTitle;
              existing.hasWindow = true;
            }

            return;
          }

          uniqueApplications.set(entry.processKey, {
            name: entry.name,
            process: entry.process,
            processName: entry.processName,
            path: entry.path,
            mainWindowTitle: entry.mainWindowTitle,
            hasWindow: entry.hasWindow,
            instanceCount: 1
          });
        });

      return Array.from(uniqueApplications.values()).sort((left, right) => {
        if (left.hasWindow !== right.hasWindow) {
          return left.hasWindow ? -1 : 1;
        }

        return left.name.localeCompare(right.name);
      });
    } catch (error) {
      this._log('list_running_applications error:', error);
      return [];
    }
  }

  async getFocusedApplication() {
    if (os.platform() !== 'win32') {
      return {
        success: false,
        error: 'unsupported-platform'
      };
    }

    try {
      const parsed = await this._focusServer.run('get', {});

      return parsed && typeof parsed === 'object'
        ? parsed
        : { success: false, error: 'invalid-response' };
    } catch (error) {
      this._log('get_focused_application error:', error);
      return {
        success: false,
        error: 'focused-application-failed'
      };
    }
  }

  async prewarm() {
    try {
      await this.getFocusedApplication();
    } catch (error) {
      this._log('focused-application prewarm error:', error);
    }
  }

  shutdown() {
    this._focusServer.shutdown();
  }
}

module.exports = { ProcessCatalog };

/**
 * PowerShellServer — shared lifecycle management for long-running PowerShell
 * worker processes that speak JSON over stdin/stdout.
 *
 * Subclasses (AudioDeviceManager, ProcessCatalog, AudioSessionBridge) all follow
 * the same pattern: lazy spawn, JSON request/response over readline (or manual
 * buffer), timeout, crash recovery.  This class extracts that wiring so it lives
 * in one place.
 */

const { spawn } = require('child_process');
const readline = require('readline');

const DEFAULT_REQUEST_TIMEOUT_MS = 8000;

/**
 * @typedef {Object}  PowerShellServerOptions
 * @property {Function}           log                        Logging function (level, ...args).
 * @property {string}             scriptPath                 Absolute path to the .ps1 worker script.
 * @property {string[]}          [spawnArgs=[]]             Extra args appended after the script path.
 *                                                         audio-sessions passes [] here; audio-devices
 *                                                         and processes pass ['-Action','serve'].
 * @property {number}             [requestTimeoutMs]         Timeout for each request (default 8000).
 * @property {'ok'|'success'}     [responseSuccessKey]       Which field on the parsed JSON marks a
 *                                                         successful response.  Default 'ok'.
 * @property {string}             [logPrefix]                Prepended to all log output.
 * @property {'readline'|'manual'}[buffering]                How to collect lines from stdout.
 *                                                         Default 'readline'.  audio-sessions uses
 *                                                         'manual' because it needs to handle binary
 *                                                         output.
 * @property {Function}           [fallbackRun]               Optional async fn (action, payload) used as
 *                                                         a fallback when the server process is
 *                                                         unavailable.  audio-sessions passes
 *                                                         runWithScript here.
 */

/**
 * @typedef {Object}  PendingRequest
 * @property {Function} resolve   Promise resolve callback.
 * @property {Function} reject    Promise reject callback.
 * @property {number}  timeoutId  Node.js timeout handle — cleared on response or reset.
 */

class PowerShellServer {
  /**
   * @param {PowerShellServerOptions} options
   */
  constructor(options) {
    if (!options?.scriptPath) {
      throw new Error('PowerShellServer: scriptPath is required');
    }

    /** @type {Function} */
    this._log = options.log || (() => {});

    /** @type {string} */
    this._scriptPath = options.scriptPath;

    /** @type {string[]} */
    this._spawnArgs = Array.isArray(options.spawnArgs) ? options.spawnArgs : [];

    /** @type {number} */
    this._requestTimeoutMs =
      typeof options.requestTimeoutMs === 'number'
        ? options.requestTimeoutMs
        : DEFAULT_REQUEST_TIMEOUT_MS;

    /** @type {'ok'|'success'} */
    this._responseSuccessKey = options.responseSuccessKey || 'ok';

    /** @type {string} */
    this._logPrefix = options.logPrefix || 'powershell-server';

    /** @type {'readline'|'manual'} */
    this._buffering = options.buffering || 'readline';

    /** @type {Function|undefined} */
    this._fallbackRun = options.fallbackRun;

    // --- protected state ---------------------------------------------------
    /** @type {import('child_process').ChildProcess|null} */
    this._process = null;

    /** @type {readline.Interface|null} */
    this._readlineInterface = null;

    /** @type {string} */
    this._buffer = '';

    /** @type {number} */
    this._requestId = 0;

    /** @type {Map<string, PendingRequest>} */
    this._pending = new Map();
  }

  // -------------------------------------------------------------------------
  // Lifecycle
  // -------------------------------------------------------------------------

  /**
   * Lazily start the worker process.  Returns the existing handle if the process
   * is already running.
   *
   * @returns {import('child_process').ChildProcess}
   */
  ensureProcess() {
    if (this._process && !this._process.killed) {
      return this._process;
    }

    const proc = spawn('powershell.exe', this._buildSpawnArgs(), {
      windowsHide: true,
      stdio: ['pipe', 'pipe', 'pipe']
    });

    proc.stdout.setEncoding('utf8');
    proc.stderr.setEncoding('utf8');

    if (this._buffering === 'manual') {
      this._attachManualBufferHandlers(proc);
    } else {
      this._attachReadlineHandlers(proc);
    }

    proc.on('error', (error) => {
      this._log(`${this._logPrefix} error:`, error);
      this._resetState(error);
    });

    proc.on('exit', (code, signal) => {
      const exitError = new Error(
        `${this._logPrefix}-exit:${code ?? 'null'}:${signal ?? 'null'}`
      );
      this._log(`${this._logPrefix} exit:`, { code, signal });
      this._resetState(exitError);
    });

    this._process = proc;
    return proc;
  }

  /**
   * Tear down the worker process and reject all pending requests.
   *
   * @param {string|Error} [reason]
   */
  stopProcess(reason) {
    const proc = this._process;

    if (!proc) {
      return;
    }

    this._process = null;
    this._clearBuffering();

    // Reject pending requests with a consistent error shape.
    const workerError =
      reason instanceof Error
        ? reason
        : new Error(String(reason || `${this._logPrefix}-stopped`));

    const pending = Array.from(this._pending.values());
    this._pending.clear();
    pending.forEach((entry) => {
      if (entry.timeoutId) clearTimeout(entry.timeoutId);
      entry.reject(workerError);
    });

    proc.removeAllListeners();
    proc.stdout?.removeAllListeners();
    proc.stderr?.removeAllListeners();

    try {
      if (!proc.killed) proc.kill();
    } catch (e) {
      this._log(`${this._logPrefix} kill error:`, e);
    }
  }

  /** Convenience: stopProcess('shutdown'). */
  shutdown() {
    this.stopProcess(`${this._logPrefix}-shutdown`);
  }

  // -------------------------------------------------------------------------
  // Request / response
  // -------------------------------------------------------------------------

  /**
   * Send a JSON-serialised payload to the worker and wait for the matching
   * response.  The payload is merged with an auto-incremented request `id`.
   *
   * @param {string} action   The action name passed to the worker.
   * @param {object} [payload={}]  Extra fields merged into the JSON payload.
   * @returns {Promise<unknown>}
   */
  async run(action, payload = {}) {
    try {
      const proc = this.ensureProcess();
      const requestId = String(++this._requestId);

      const promise = new Promise((resolve, reject) => {
        const timeoutId = setTimeout(() => {
          if (this._pending.has(requestId)) {
            this._pending.delete(requestId);
          }
          reject(
            new Error(`${this._logPrefix}-timeout:${action || 'unknown'}`)
          );
        }, this._requestTimeoutMs);

        this._pending.set(requestId, { resolve, reject, timeoutId });
      });

      const json = JSON.stringify({ id: requestId, action, ...payload });
      proc.stdin.write(json + '\n');

      return await promise;
    } catch (error) {
      this._log(`${this._logPrefix} run error, trying fallback:`, error);
      if (this._fallbackRun) {
        return this._fallbackRun(action, payload);
      }
      throw error;
    }
  }

  // -------------------------------------------------------------------------
  // Protected override points
  // -------------------------------------------------------------------------

  /**
   * Build the full spawn argument array for the worker process.
   * Override to customise the argument list (e.g. when no `-Action serve` is needed).
   *
   * @returns {string[]}
   * @protected
   */
  _buildSpawnArgs() {
    return [
      '-NoProfile',
      '-ExecutionPolicy',
      'Bypass',
      '-File',
      this._scriptPath,
      ...this._spawnArgs
    ];
  }

  /**
   * Parse a single line of stdout into a response object.
   * audio-sessions overrides this to also check for `success === false`.
   *
   * @param {string} line  A trimmed, non-empty line from stdout.
   * @returns {{ id: string, [key: string]: unknown }}
   * @throws {Error} When the line cannot be parsed as JSON.
   * @protected
   */
  _parseLine(line) {
    return JSON.parse(line);
  }

  /**
   * Resolve or reject a pending request based on a parsed response.
   * Calls _isSuccess() to check the appropriate success key.
   *
   * @param {PendingRequest} pending
   * @param {object}         parsedMessage
   * @protected
   */
  _onResponse(pending, parsedMessage) {
    if (this._isSuccess(parsedMessage)) {
      pending.resolve(parsedMessage.result ?? null);
    } else {
      pending.reject(
        new Error(
          String(
            parsedMessage?.error || parsedMessage?.Error || `${this._logPrefix}-error`
          )
        )
      );
    }
  }

  /**
   * Check whether a parsed response represents a successful result.
   *
   * @param {object} parsedMessage
   * @returns {boolean}
   * @protected
   */
  _isSuccess(parsedMessage) {
    const key = this._responseSuccessKey;
    return parsedMessage[key] !== false;
  }

  // -------------------------------------------------------------------------
  // Internal helpers
  // -------------------------------------------------------------------------

  /**
   * Readline-based line collection (used when buffering === 'readline').
   * @param {import('child_process').ChildProcess} proc
   * @private
   */
  _attachReadlineHandlers(proc) {
    const rl = readline.createInterface({
      input: proc.stdout,
      crlfDelay: Infinity
    });

    rl.on('line', (rawLine) => {
      const line = String(rawLine || '').trim();
      if (!line) return;

      let parsedMessage;
      try {
        parsedMessage = this._parseLine(line);
      } catch (e) {
        this._log(`${this._logPrefix} parse error:`, e, line);
        return;
      }

      const requestId = String(parsedMessage?.id || '').trim();
      const pending = this._pending.get(requestId);
      if (!pending) return;

      this._pending.delete(requestId);
      if (pending.timeoutId) clearTimeout(pending.timeoutId);

      this._onResponse(pending, parsedMessage);
    });

    proc.stderr.on('data', (chunk) => {
      const msg = String(chunk || '').trim();
      if (msg) this._log(`${this._logPrefix} stderr:`, msg);
    });

    this._readlineInterface = rl;
  }

  /**
   * Manual buffer-based line collection (used when buffering === 'manual').
   * Subclasses may override _parseLine; this method calls it for each complete
   * line found in the growing buffer.
   *
   * @param {import('child_process').ChildProcess} proc
   * @private
   */
  _attachManualBufferHandlers(proc) {
    proc.stdout.on('data', (chunk) => {
      this._buffer += chunk;

      while (true) {
        const nl = this._buffer.indexOf('\n');
        if (nl === -1) break;

        const line = this._buffer.slice(0, nl).trim();
        this._buffer = this._buffer.slice(nl + 1);

        if (!line) continue;

        let parsedMessage;
        try {
          parsedMessage = this._parseLine(line);
        } catch (e) {
          this._log(`${this._logPrefix} parse error:`, e, line);
          continue;
        }

        const requestId = String(parsedMessage?.id || '').trim();
        const pending = this._pending.get(requestId);
        if (!pending) continue;

        this._pending.delete(requestId);
        if (pending.timeoutId) clearTimeout(pending.timeoutId);

        this._onResponse(pending, parsedMessage);
      }
    });

    proc.stderr.on('data', (chunk) => {
      const msg = String(chunk || '').trim();
      if (msg) this._log(`${this._logPrefix} stderr:`, msg);
    });
  }

  /**
   * Tear down buffering resources without killing the process.
   * Called by _resetState() and stopProcess().
   *
   * @private
   */
  _clearBuffering() {
    if (this._readlineInterface) {
      this._readlineInterface.removeAllListeners();
      this._readlineInterface.close();
      this._readlineInterface = null;
    }
    this._buffer = '';
  }

  /**
   * Internal full reset — called by the 'error' and 'exit' handlers.
   * Tears down buffering, kills the process, and rejects all pending requests.
   *
   * @param {Error} [error]
   * @private
   */
  _resetState(error) {
    const proc = this._process;
    this._process = null;
    this._clearBuffering();

    const pending = Array.from(this._pending.values());
    this._pending.clear();
    pending.forEach((entry) => {
      if (entry.timeoutId) clearTimeout(entry.timeoutId);
      entry.reject(error || new Error(`${this._logPrefix}-closed`));
    });

    if (!proc) return;

    proc.removeAllListeners();
    proc.stdout?.removeAllListeners();
    proc.stderr?.removeAllListeners();

    try {
      if (!proc.killed) proc.kill();
    } catch (e) {
      this._log(`${this._logPrefix} kill error:`, e);
    }
  }
}

module.exports = { PowerShellServer };

