```javascript
// test/contract-parity-focus.js

const nativeFocus = require('../backend/native-focus');
const { PowerShellServer } = require('../backend/powershell-server');

async function testFocusedAppContract() {
  console.log('[contract-parity] Testing focused app...');

  // Run both implementations
  const [nativeResult, psResult] = await Promise.all([
    nativeFocus.getFocusedWindow(),
    runPowerShellFocusedApp()
  ]);

  // Compare structure
  const nativeKeys = Object.keys(nativeResult.application || {}).sort();
  const psKeys = Object.keys(psResult.application || {}).sort();

  if (JSON.stringify(nativeKeys) !== JSON.stringify(psKeys)) {
    console.error('[contract-parity] MISMATCH: Field presence differs');
    console.error('Native fields:', nativeKeys);
    console.error('PowerShell fields:', psKeys);
    process.exit(1);
  }

  // Compare types
  for (const key of nativeKeys) {
    const nativeType = typeof nativeResult.application[key];
    const psType = typeof psResult.application[key];

    if (nativeType !== psType) {
      console.error(`[contract-parity] MISMATCH: ${key} type differs`);
      console.error(`  Native: ${nativeType}, PowerShell: ${psType}`);
      process.exit(1);
    }
  }

  console.log('[contract-parity] ✓ Focused app contract matches');
}
