  const baseName = String(processFile || '')
    .replace(/\.exe$/i, '')
    .replace(/[_-]+/g, ' ')
    .trim();

  if (!baseName) {
    return 'Unknown app';
  }

  return baseName.replace(/\b\w/g, (match) => match.toUpperCase());
}

module.exports = {
  getFocusedWindow,
  focusWindowByPid,
  isAvailable: () => USE_NATIVE_FOCUS && nativeFocus !== null,
};

