const nativeFocus = require('../backend/native-focus');
const { PowerShellServer } = require('../backend/powershell-server');
const path = require('path');

const FOCUSED_SCRIPT_PATH = path.join(
  __dirname,
  '../backend/scripts/focused-application.ps1'
);

async function runPowerShellFocusedApp() {
  const server = new PowerShellServer({
    log: () => {},
    scriptPath: FOCUSED_SCRIPT_PATH,
    spawnArgs: ['-Action', 'serve'],
    requestTimeoutMs: 3000,
    responseSuccessKey: 'ok',
    logPrefix: 'focused-application-test',
    buffering: 'readline',
  });

  try {
    const result = await server.run('get', {});
    server.shutdown();
    return result;
  } catch (error) {
    server.shutdown();
    throw error;
  }
}

async function testFocusedAppContract() {
  console.log('\n[contract-parity] Testing focused app contract...\n');

  if (!nativeFocus.isAvailable()) {
    console.error('[contract-parity] ❌ Native focus module not available');
    console.error('[contract-parity] Build the native module first: cd faderdeck-native && npm run build');
    process.exit(1);
  }

  try {
    // Run both implementations
    console.log('[contract-parity] Running native implementation...');
    const nativeResult = await nativeFocus.getFocusedWindow();

    console.log('[contract-parity] Running PowerShell implementation...');
    const psResult = await runPowerShellFocusedApp();

    console.log('\n[contract-parity] Native result:', JSON.stringify(nativeResult, null, 2));
    console.log('\n[contract-parity] PowerShell result:', JSON.stringify(psResult, null, 2));

    // Compare top-level structure
    if (nativeResult.success !== psResult.success) {
      console.error('\n[contract-parity] ❌ MISMATCH: success field differs');
      console.error(`  Native: ${nativeResult.success}, PowerShell: ${psResult.success}`);
      process.exit(1);
    }

    if (!nativeResult.success && !psResult.success) {
      console.log('\n[contract-parity] ✓ Both implementations returned failure (no focused window)');
      return;
    }

    // Compare application object structure
    const nativeApp = nativeResult.application || {};
    const psApp = psResult.application || {};

    const nativeKeys = Object.keys(nativeApp).sort();
    const psKeys = Object.keys(psApp).sort();

    if (JSON.stringify(nativeKeys) !== JSON.stringify(psKeys)) {
      console.error('\n[contract-parity] ❌ MISMATCH: Field presence differs');
      console.error('  Native fields:', nativeKeys);
      console.error('  PowerShell fields:', psKeys);
      process.exit(1);
    }

    // Compare types
    for (const key of nativeKeys) {
      const nativeType = typeof nativeApp[key];
      const psType = typeof psApp[key];

      if (nativeType !== psType) {
        console.error(`\n[contract-parity] ❌ MISMATCH: ${key} type differs`);
        console.error(`  Native: ${nativeType}, PowerShell: ${psType}`);
        process.exit(1);
      }
    }

    // Compare specific field values (should be identical for same window)
    if (nativeApp.pid !== psApp.pid) {
      console.warn(`\n[contract-parity] ⚠️  WARNING: PIDs differ (window may have changed)`);
      console.warn(`  Native: ${nativeApp.pid}, PowerShell: ${psApp.pid}`);
    }

    console.log('\n[contract-parity] ✓ Focused app contract matches');
    console.log('[contract-parity] ✓ All fields present');
    console.log('[contract-parity] ✓ All types match');
    console.log('\n[contract-parity] SUCCESS: Contract parity validated\n');
  } catch (error) {
    console.error('\n[contract-parity] ❌ Test failed:', error);
    process.exit(1);
  }
}

if (require.main === module) {
  testFocusedAppContract();
}

module.exports = { testFocusedAppContract };

