const path = require('path');

const execFileAsync = promisify(execFile);
const SCRIPT_PATH = path.join(__dirname, '../backend/scripts/process-list.ps1');

async function runPowerShellProcessList() {
  const { stdout } = await execFileAsync(
    'powershell.exe',
    ['-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', SCRIPT_PATH],
    { windowsHide: true, maxBuffer: 10 * 1024 * 1024 }
  );

  const parsed = JSON.parse(stdout);
  return Array.isArray(parsed) ? parsed : [parsed];
}

async function testProcessListContract() {
  console.log('\n[contract-parity] Testing process list contract...\n');

  if (!nativeProcesses.isAvailable()) {
    console.error('[contract-parity] ❌ Native processes module not available');
    console.error('[contract-parity] Build the native module first: cd faderdeck-native && npm run build');
    process.exit(1);
  }

  try {
    // Run both implementations
    console.log('[contract-parity] Running native implementation...');
    const nativeResult = await nativeProcesses.listProcesses();

    console.log('[contract-parity] Running PowerShell implementation...');
    const psResult = await runPowerShellProcessList();

    console.log(`\n[contract-parity] Native returned ${nativeResult.length} processes`);
    console.log(`[contract-parity] PowerShell returned ${psResult.length} processes`);

    if (nativeResult.length === 0 || psResult.length === 0) {
      console.error('\n[contract-parity] ❌ One implementation returned no processes');
      process.exit(1);
    }

    // Compare structure of first process from each
    const nativeSample = nativeResult[0];
    const psSample = psResult[0];

    console.log('\n[contract-parity] Native sample:', JSON.stringify(nativeSample, null, 2));
    console.log('\n[contract-parity] PowerShell sample:', JSON.stringify(psSample, null, 2));

    const nativeKeys = Object.keys(nativeSample).sort();
    const psKeys = Object.keys(psSample).sort();

    if (JSON.stringify(nativeKeys) !== JSON.stringify(psKeys)) {
      console.error('\n[contract-parity] ❌ MISMATCH: Field presence differs');
      console.error('  Native fields:', nativeKeys);
      console.error('  PowerShell fields:', psKeys);
      process.exit(1);
    }

    // Compare types
    for (const key of nativeKeys) {
      const nativeType = typeof nativeSample[key];
      const psType = typeof psSample[key];

      if (nativeType !== psType) {
        console.error(`\n[contract-parity] ❌ MISMATCH: ${key} type differs`);
        console.error(`  Native: ${nativeType}, PowerShell: ${psType}`);
        process.exit(1);
      }
    }

    // Check that both have some windowed apps
    const nativeWindowed = nativeResult.filter((p) => p.hasWindow).length;
    const psWindowed = psResult.filter((p) => p.hasWindow).length;

    console.log(`\n[contract-parity] Native windowed apps: ${nativeWindowed}`);
    console.log(`[contract-parity] PowerShell windowed apps: ${psWindowed}`);

    if (nativeWindowed === 0 || psWindowed === 0) {
      console.warn('\n[contract-parity] ⚠️  WARNING: One implementation found no windowed apps');
    }

    // Check for common processes (should have significant overlap)
    const nativeProcessNames = new Set(nativeResult.map((p) => p.process.toLowerCase()));
    const psProcessNames = new Set(psResult.map((p) => p.Process.toLowerCase()));

    const commonProcesses = [...nativeProcessNames].filter((name) =>
      psProcessNames.has(name)
    );

    const overlapPercent = (commonProcesses.length / Math.min(nativeProcessNames.size, psProcessNames.size)) * 100;

    console.log(`\n[contract-parity] Process overlap: ${commonProcesses.length} common (${overlapPercent.toFixed(1)}%)`);

    if (overlapPercent < 50) {
      console.warn('\n[contract-parity] ⚠️  WARNING: Low process overlap, implementations may differ significantly');
    }

    console.log('\n[contract-parity] ✓ Process list contract matches');
    console.log('[contract-parity] ✓ All fields present');
    console.log('[contract-parity] ✓ All types match');
    console.log('\n[contract-parity] SUCCESS: Contract parity validated\n');
  } catch (error) {
    console.error('\n[contract-parity] ❌ Test failed:', error);
    process.exit(1);
  }
}

if (require.main === module) {
  testProcessListContract();
}

module.exports = { testProcessListContract };

